  && (HOUSE_RE.test([d.address_building, d.address_street, d.address_notes, d.address_landmark].map(str).join(' '))
      || !!str(d.comes_down)
      || COMES_DOWN_RE.test([d.address_notes, d.order_notes].map(str).join(' '))));
