  return frac ? `${w} و${frac}` : w;
};
const item = $('Prepare Apology').first().json;
const r = $input.first().json || {};
const body = obj(r.body && typeof r.body === 'object' ? r.body : r);
const id = str(obj(body.key).id) || null;
const ok = !!id && !r.error;
return [{
  json: {
    b64_log: b64({
      tenant_id: item.tenant_id, wa_id: item.wa_id, run_id: item.run_id, sender: 'system', kind: 'text',
      body: item.text, external_id: id, ok,
      error: ok ? null : str(obj(r.error).message || r.error || 'WhatsApp did not confirm the message').slice(0, 300),
      meta: { purpose: 'pause_notice' }
    })
  }
}];

// =====================================================================
// EVERWAKE — Main · NODE: Prepare Media
// A customer's photo or voice note, ready for the model that understands
// it: the file (from the webhook itself, or fetched from Evolution), the
// transcription request for a voice note, the vision request for a photo.
// What it says or shows replaces "[voice note]" / "[photo]" for the agent
// (Media Understood) before the turn starts.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
